command:
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) {
  ui.notifications.warn("Select a token or assign a character first.");
  return;
}

const existing = actor.items.find((i) => i.type === "effect" && i.system.slug === "untamed-form");
if (existing) {
  await existing.delete();
  ui.notifications.info(`${actor.name} reverts from Untamed Form.`);
  return;
}

const source = await fromUuid("Compendium.phil-pf2e-weredragon.weredragon-feats.Item.UntamedFrmWeredr");
if (!source) {
  ui.notifications.error("Could not find the homebrew Untamed Form spell effect in the module compendium.");
  return;
}

await actor.createEmbeddedDocuments("Item", [source.toObject()]);
ui.notifications.info(`${actor.name} assumes Untamed Form — choose a shape from the prompt.`);

const mod = game.modules.get("phil-pf2e-weredragon");
if (mod?.applyHealingTransformation) await mod.applyHealingTransformation(actor);
